def fill_search_text(apps, schema_editor):
    """Mavjud yozuvlar: mahsulot nomi va biznes matniga katalog (Business.build_search_text bilan bir xil)."""
    Item = apps.get_model("businesses", "Item")
    Business = apps.get_model("businesses", "Business")
    for item in Item.objects.all().only("id", "name"):
        Item.objects.filter(pk=item.pk).update(search_text=normalize_for_search(item.name))
    for business in Business.objects.select_related("category__parent", "district"):
        category = business.category
        parts = [business.name, category.name_uz, category.name_ru]
        if category.parent:
            parts += [category.parent.name_uz, category.parent.name_ru]
        parts += [business.district.name_uz, business.district.name_ru]
        for name, group in Item.objects.filter(business=business).values_list("name", "group"):
            parts += [name, group]
        Business.objects.filter(pk=business.pk).update(
            search_text=normalize_for_search(" ".join(parts))
        )


